// spec: specs/orders.md §28 · кейсы .qa/tests/orders/ord-40-edit-price-field-width.md (п. 7), ord-38
// seed: tests/seed.admin.spec.ts
// #f621b3 (עבר QA 27.10, commit 0642b35): «עריכת הזמנה» — подпись «סה"כ לתשלום» всегда в одну строку (≈20px, не 40) и при длинной
//   сумме (₪1,000,001.00); сумма видна целиком — рядом или строкой ниже у левого края (оба варианта допустимы, «מה רצוי» — «או עובר
//   לשורה מתחת»); без горизонтальной прокрутки. Контроль ₪10.00 — подпись и сумма в одной строке.
//   Ширины тикета: 1024 с боковым меню и 320 (телефон); регресс 360–1440.
// Без сохранения: в конце «ביטול», заказ прежний «— 2 × ₪5.00 ₪10.00». (Вручную — заказ #490; в автотесте свой заказ.)
// Данные: товар QA-AUTO-f621-<ts> (₪5, остаток 3 «ללא מקום») + заказ клиента test ×2 («ממתינה לאישור»); afterAll — отклонить, удалить.
// buyerPlaceOrder очищает корзину buyer → @data, не параллельно с тестами корзины. Телефонные ширины — эмуляцией ширины в том же
//   проекте (@desktop, как вручную «320 emu»): один beforeAll → один заказ, без гонки за общую корзину между проектами.
import { test, expect, Page } from '@playwright/test';
import { auth, createStockedProduct, buyerPlaceOrder, openOrder, cleanup } from './_qa-order';

test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const ts = `${String(Date.now()).slice(-7)}${Math.floor(Math.random() * 10)}`;
const P = `QA-AUTO-f621-${ts}`;
let orderNo: string | undefined;
let productCreated = false;

const LONG = '₪1,000,001.00';
const SHORT = '₪10.00';
const price = (page: Page) => page.getByRole('spinbutton', { name: `מחיר יחידה — ${P}`, exact: true });
const cardRow = (page: Page) => page.getByText(P, { exact: true }).first().locator('..');

/** Замер строки «סה"כ לתשלום» и карточки «פריטי ההזמנה» (только чтение DOM). */
const measure = (page: Page) => page.evaluate(() => {
  const bx = (e: Element) => { const b = e.getBoundingClientRect(); return { l: b.left, t: b.top, r: b.right, b: b.bottom, h: b.height, cy: (b.top + b.bottom) / 2 }; };
  const h = [...document.querySelectorAll('h1,h2,h3,h4')].find((e) => e.textContent!.trim() === 'פריטי ההזמנה')!;
  const card = h.parentElement!;
  const lab = [...card.querySelectorAll('*')].find((e) => e.children.length === 0 && e.textContent!.trim() === 'סה"כ לתשלום')!;
  const amt = [...lab.parentElement!.querySelectorAll('*')].find((e) => e !== lab && e.children.length === 0 && /₪/.test(e.textContent || ''))!;
  const s = getComputedStyle(lab);
  return {
    vw: innerWidth, docSW: document.documentElement.scrollWidth, scrollX, card: bx(card), cardSW: card.scrollWidth, cardCW: card.clientWidth,
    lab: bx(lab), labLH: parseFloat(s.lineHeight) || 20, labWS: s.whiteSpace, labRects: lab.getClientRects().length,
    amt: bx(amt), amtText: amt.textContent!.trim(), amtClip: amt.scrollWidth > amt.clientWidth + 1,
  };
});

const inside = (a: { l: number; r: number }, c: { l: number; r: number }) => a.l >= c.l - 0.5 && a.r <= c.r + 0.5;

async function setPrice(page: Page, v: string, expectTotal: string) {
  await price(page).fill(v);
  await price(page).press('Tab');
  await expect(page.getByText('סה"כ לתשלום', { exact: true }).locator('..'), `«סה"כ לתשלום» = ${expectTotal}`).toContainText(expectTotal);
}

/** Проверки одной ширины: длинная сумма, затем контроль ₪10.00. */
async function checkWidth(page: Page, W: number, H: number, menuOpen = false) {
  await page.setViewportSize({ width: W, height: H });
  await expect.poll(() => page.evaluate(() => innerWidth)).toBe(W);
  if (menuOpen) await expect(page.getByRole('button', { name: /^כיווץ/ }), `${W}: боковое меню открыто`).toBeVisible();

  await setPrice(page, '500000.50', LONG);
  let m = await measure(page);
  let tag = `${W}×${H}, ${LONG}`;
  // подпись — одна строка (было «סה"כ / לתשלום», 40px)
  expect(m.lab.h, `${tag}: «סה"כ לתשלום» в одну строку (высота ${m.lab.h}px)`).toBeLessThanOrEqual(m.labLH + 1);
  expect(m.labRects, `${tag}: подпись не разбита на строки`).toBe(1);
  // сумма целиком, в карточке и экране; рядом (одна строка) или ниже подписи у левого края — RTL
  expect(m.amtText, `${tag}: сумма`).toBe(LONG);
  expect(m.amtClip, `${tag}: сумма не обрезана`).toBe(false);
  expect(inside(m.amt, m.card) && inside(m.lab, m.card), `${tag}: подпись и сумма внутри карточки`).toBe(true);
  expect(inside(m.amt, { l: 0, r: m.vw }), `${tag}: сумма внутри экрана`).toBe(true);
  const sameRow = Math.abs(m.amt.cy - m.lab.cy) <= 6;
  if (sameRow) expect(m.amt.r, `${tag}: в одной строке — сумма слева от подписи`).toBeLessThanOrEqual(m.lab.l + 0.5);
  else expect(m.amt.t, `${tag}: перенос — сумма строкой ниже подписи`).toBeGreaterThanOrEqual(m.lab.b - 1);
  expect(m.amt.l - m.card.l, `${tag}: сумма у левого края карточки`).toBeLessThanOrEqual(40);
  // без горизонтальной прокрутки
  expect(m.docSW, `${tag}: страница без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
  expect(m.scrollX, `${tag}: окно не прокручено вбок`).toBe(0);
  expect(m.cardSW, `${tag}: карточка без прокрутки вбок`).toBeLessThanOrEqual(m.cardCW + 1);

  // контроль: обычная сумма — подпись и сумма в одной строке («מה קיים» — «בסכום רגיל… בשורה אחת»)
  await setPrice(page, '5', SHORT);
  m = await measure(page);
  tag = `${W}×${H}, ${SHORT}`;
  expect(m.lab.h, `${tag}: подпись в одну строку`).toBeLessThanOrEqual(m.labLH + 1);
  expect(m.amtText, `${tag}: сумма`).toBe(SHORT);
  expect(Math.abs(m.amt.cy - m.lab.cy), `${tag}: подпись и сумма в одной строке`).toBeLessThanOrEqual(6);
  expect(m.amt.r, `${tag}: сумма слева от подписи (RTL)`).toBeLessThanOrEqual(m.lab.l + 0.5);
}

async function openEdit(page: Page) {
  await page.setViewportSize({ width: 1440, height: 900 });
  await openOrder(page, orderNo!);
  await page.getByRole('button', { name: 'עריכה', exact: true }).click();
  await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
  await expect(price(page)).toBeVisible();
}

async function cancelAndCheckUnchanged(page: Page) {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
  await page.reload();
  await expect(cardRow(page), 'заказ не изменился (после reload)').toHaveText(/—\s*2\s*×?\s*₪5\.00\s*₪10\.00/, { timeout: 20_000 });
}

test.describe('orders — עריכת הזמנה: «סה"כ לתשלום» בשורה אחת גם בסכום ארוך (#f621b3)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(240_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    let id: string;
    try {
      productCreated = true;
      id = await createStockedProduct(await ctx.newPage(), P, `QAF621-${ts}`, 5, 3);
    } finally { await ctx.close(); }
    orderNo = await buyerPlaceOrder(browser, [{ id, name: P, qty: 2 }], `QA-AUTO-f621-${ts}`);
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [orderNo], productCreated ? [P] : []);
  });

  test('1024 עם תפריט צד: ₪1,000,001.00 — הכיתוב בשורה אחת, הסכום במלואו; רגרסיה 641/768/1100/1280/1440 #f621b3 @desktop @orders @data', async ({ page }) => {
    test.setTimeout(240_000);
    await openEdit(page);
    await checkWidth(page, 1024, 768, true);
    for (const [w, h] of [[641, 900], [768, 1024], [1100, 800], [1280, 800], [1440, 900]] as const) await checkWidth(page, w, h);
    await cancelAndCheckUnchanged(page);
  });

  test('טלפון 320 (+360/390/414, רוחב באמולציה): ₪1,000,001.00 — הכיתוב בשורה אחת, הסכום במלואו, בלי גלילה לרוחב #f621b3 @desktop @orders @data', async ({ page }) => {
    test.setTimeout(240_000);
    await openEdit(page);
    for (const [w, h] of [[320, 568], [360, 740], [390, 844], [414, 896]] as const) await checkWidth(page, w, h);
    await cancelAndCheckUnchanged(page);
  });
});
